import{_ as a,o as n,c as s,b6 as t,cp as i,cq as o,cr as l,cs as r,ct as p,cu as g,cv as c,cw as d}from"./chunks/framework.COUcLbTA.js";const P=JSON.parse('{"title":"Designing Websites with Design and Programming Agents","description":"","frontmatter":{},"headers":[],"relativePath":"en/stage-1/appendix-articles/example0-2/vibe-coding-tools-build-website-with-ai-coding-and-design-agents.md","filePath":"en/stage-1/appendix-articles/example0-2/vibe-coding-tools-build-website-with-ai-coding-and-design-agents.md"}'),h={name:"en/stage-1/appendix-articles/example0-2/vibe-coding-tools-build-website-with-ai-coding-and-design-agents.md"};function u(m,e,b,f,k,y){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="designing-websites-with-design-and-programming-agents" tabindex="-1">Designing Websites with Design and Programming Agents <a class="header-anchor" href="#designing-websites-with-design-and-programming-agents" aria-label="Permalink to “Designing Websites with Design and Programming Agents”">​</a></h1><h2 id="chapter-introduction" tabindex="-1">Chapter Introduction <a class="header-anchor" href="#chapter-introduction" aria-label="Permalink to “Chapter Introduction”">​</a></h2><p>This chapter demonstrates how design and development can work together perfectly through AI. You will play the role of a product manager, directing the &quot;Design Agent&quot; to complete logo design, color schemes, and page layouts, then collaborate with the &quot;Programming Agent&quot; to transform visual mockups into runnable code. Experience full-chain AI-powered development from creative conception to website launch, making one person equivalent to an entire team.</p><hr><h1 id="_1-getting-started-guide" tabindex="-1">1. Getting Started Guide <a class="header-anchor" href="#_1-getting-started-guide" aria-label="Permalink to “1. Getting Started Guide”">​</a></h1><h2 id="_1-tutorial-introduction" tabindex="-1">1. Tutorial Introduction <a class="header-anchor" href="#_1-tutorial-introduction" aria-label="Permalink to “1. Tutorial Introduction”">​</a></h2><p>Let&#39;s use AI Design Agents and Coding Agents to build a complete website from scratch.</p><ul><li><strong>Design Agent</strong>: Responsible for creating logos, web page layouts, color schemes, and other visual elements</li><li><strong>Coding Agent</strong>: Writes actual code (HTML/CSS/JS, etc.) based on the requirements and layouts you provide in prompts to build a runnable website</li></ul><h2 id="_2-design-agents-vs-coding-agents" tabindex="-1">2. Design Agents vs. Coding Agents <a class="header-anchor" href="#_2-design-agents-vs-coding-agents" aria-label="Permalink to “2. Design Agents vs. Coding Agents”">​</a></h2><ul><li><strong>Design Agent</strong>: AI that generates images, page mockups, or design styles based on the prompts you provide. <ul><li>Mastergo</li><li>Lovart</li><li>Figma MCP</li></ul></li><li><strong>Coding Agent</strong>: AI that writes actual code (HTML/CSS/JS, etc.) based on the functionality and layout you request in prompts. <ul><li>Z.AI</li><li>Trae</li><li>Cursor</li><li>Lovable</li></ul></li></ul><hr><h1 id="_2-using-design-agent-to-create-logo" tabindex="-1">2. Using Design Agent to Create Logo <a class="header-anchor" href="#_2-using-design-agent-to-create-logo" aria-label="Permalink to “2. Using Design Agent to Create Logo”">​</a></h1><h2 id="_1-key-elements-to-consider-when-designing-a-logo" tabindex="-1">1. Key Elements to Consider When Designing a Logo <a class="header-anchor" href="#_1-key-elements-to-consider-when-designing-a-logo" aria-label="Permalink to “1. Key Elements to Consider When Designing a Logo”">​</a></h2><p>The logo is one of the key elements that determine your website&#39;s first impression. To get satisfactory results from AI Design Agents, you need to clearly describe the type of logo you want in your prompt.</p><ol><li><strong>Brand Name / Text</strong></li></ol><ul><li>Text that must appear in the logo (e.g., website title, brand name, etc.).</li></ul><ol start="2"><li><strong>Style (Mood / Atmosphere)</strong></li></ol><ul><li>The overall feeling or atmosphere the logo wants to convey.</li><li><em>Examples: minimalist, cute, simple, modern, vintage, futuristic, etc.</em></li></ul><ol start="3"><li><strong>Color Scheme</strong> (Optional)</li></ol><ul><li>It&#39;s best if the logo&#39;s colors match the overall tone of the entire website.</li><li>You can specify specific hex color codes, or general color tones (cool, warm, etc.).</li><li><em>Examples: <strong><code>#171721</code></strong> (black), <strong><code>#FF7130</code></strong> (orange).</em></li></ul><ol start="4"><li><strong>Form (Shape / Structure)</strong></li></ol><ul><li>Clearly state if the logo needs a specific shape or composition.</li><li><em>Examples: text inside a circle, icon + text combination, icon-focused logo, etc.</em></li></ul><ol start="5"><li><strong>Icon / Symbol Elements</strong> (Optional)</li></ol><ul><li>Graphics or symbols you want to appear in the logo.</li><li><em>Examples: book icon, lightning symbol, AI-related graphics, abstract geometric shapes, etc.</em></li></ul><h2 id="_2-writing-logo-design-prompts" tabindex="-1">2. Writing Logo Design Prompts <a class="header-anchor" href="#_2-writing-logo-design-prompts" aria-label="Permalink to “2. Writing Logo Design Prompts”">​</a></h2><p><strong>Example Prompts</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;Please design a minimalist-style logo for me, with the brand name &#39;My First Website&#39;.</span></span>
<span class="line"><span>Use black (#171721) and orange (#FF7130), and place the text inside a circle.&quot;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;Design a logo with the brand name &#39;AIID&#39;.</span></span>
<span class="line"><span>The overall style should be futuristic, clean, and simple, with blue and white as the main colors.</span></span>
<span class="line"><span>Combine abstract graphics symbolizing AI with the text, and export as a PNG with a transparent background.&quot;</span></span></code></pre></div><h2 id="_3-requesting-design-from-agent" tabindex="-1">3. Requesting Design from Agent <a class="header-anchor" href="#_3-requesting-design-from-agent" aria-label="Permalink to “3. Requesting Design from Agent”">​</a></h2><ul><li>Input the above prompts → Compare multiple designs generated by the Agent.</li></ul><p><img src="`+i+'" alt=""><img src="'+o+`" alt=""></p><h2 id="_4-finalizing-the-logo" tabindex="-1">4. Finalizing the Logo <a class="header-anchor" href="#_4-finalizing-the-logo" aria-label="Permalink to “4. Finalizing the Logo”">​</a></h2><ul><li>Choose your favorite version from the drafts and download it.</li></ul><hr><h1 id="_3-planning-your-website-structure" tabindex="-1">3. Planning Your Website Structure <a class="header-anchor" href="#_3-planning-your-website-structure" aria-label="Permalink to “3. Planning Your Website Structure”">​</a></h1><h2 id="_1-understanding-basic-sections" tabindex="-1">1. Understanding Basic Sections <a class="header-anchor" href="#_1-understanding-basic-sections" aria-label="Permalink to “1. Understanding Basic Sections”">​</a></h2><p>Before actually starting to build the website, it&#39;s very important to plan which menus (sections) to include. The menu design depends on what you want visitors to see and what actions you want them to take. Generally, websites are usually composed of basic sections like <strong>Home / About / Contact</strong>.</p><h2 id="_2-draw-your-own-structural-sketch-optional" tabindex="-1">2. Draw Your Own Structural Sketch (Optional) <a class="header-anchor" href="#_2-draw-your-own-structural-sketch-optional" aria-label="Permalink to “2. Draw Your Own Structural Sketch (Optional)”">​</a></h2><p>You can first write out a simple menu structure based on the website&#39;s goals.</p><hr><h1 id="_4-using-design-agent-to-create-page-layout" tabindex="-1">4. Using Design Agent to Create Page Layout <a class="header-anchor" href="#_4-using-design-agent-to-create-page-layout" aria-label="Permalink to “4. Using Design Agent to Create Page Layout”">​</a></h1><h2 id="_1-page-layout-design-prompts" tabindex="-1">1. Page Layout Design Prompts <a class="header-anchor" href="#_1-page-layout-design-prompts" aria-label="Permalink to “1. Page Layout Design Prompts”">​</a></h2><p><strong>Example Prompts</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;Please create a website layout with the following requirements:</span></span>
<span class="line"><span>- Color scheme: black (#171721) background, white text, orange (#FF7130) accents</span></span>
<span class="line"><span>- Sections: Home, About, Services, Contact</span></span>
<span class="line"><span>- Home: Hero section with large headline, CTA button, and service highlights</span></span>
<span class="line"><span>- About: Company introduction with team member photos</span></span>
<span class="line"><span>- Services: Grid layout showing services offered</span></span>
<span class="line"><span>- Contact: Simple contact form with email and social media links</span></span>
<span class="line"><span>- Style: Modern, minimalist, with smooth scroll animations&quot;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;Design a landing page for an AI tools collection website.</span></span>
<span class="line"><span>- Primary colors: purple (#7C3AED) and dark gray (#1F2937)</span></span>
<span class="line"><span>- Hero: Centered title &#39;AI Tools Hub&#39;, subtitle, and &#39;Explore Now&#39; button</span></span>
<span class="line"><span>- Features: 3-column grid showing tool categories</span></span>
<span class="line"><span>- Each card should have an icon, title, and brief description</span></span>
<span class="line"><span>- Footer: Copyright and social links</span></span>
<span class="line"><span>- Include responsive design considerations&quot;</span></span></code></pre></div><h2 id="_2-requesting-layout-design-from-agent" tabindex="-1">2. Requesting Layout Design from Agent <a class="header-anchor" href="#_2-requesting-layout-design-from-agent" aria-label="Permalink to “2. Requesting Layout Design from Agent”">​</a></h2><ul><li>Input your requirements → Agent generates layout mockups → Refine based on feedback</li></ul><p><img src="`+l+'" alt=""><img src="'+r+`" alt=""></p><h2 id="_3-creating-color-palette" tabindex="-1">3. Creating Color Palette <a class="header-anchor" href="#_3-creating-color-palette" aria-label="Permalink to “3. Creating Color Palette”">​</a></h2><p><strong>Example Prompt</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;Create a color palette for a tech blog website.</span></span>
<span class="line"><span>- Primary: Deep blue</span></span>
<span class="line"><span>- Accent: Vibrant orange</span></span>
<span class="line"><span>- Background: Light gray for readability</span></span>
<span class="line"><span>- Text: Dark gray for contrast</span></span>
<span class="line"><span>Please provide hex codes for each color and explain their usage.&quot;</span></span></code></pre></div><p><img src="`+p+`" alt=""></p><h2 id="_4-selecting-typography" tabindex="-1">4. Selecting Typography <a class="header-anchor" href="#_4-selecting-typography" aria-label="Permalink to “4. Selecting Typography”">​</a></h2><p><strong>Example Prompt</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;Recommend font pairings for a modern tech website.</span></span>
<span class="line"><span>- Heading font: Something bold and distinctive</span></span>
<span class="line"><span>- Body font: Clean and readable</span></span>
<span class="line"><span>Please suggest specific Google Fonts.&quot;</span></span></code></pre></div><hr><h1 id="_5-integrating-design-with-coding-agent" tabindex="-1">5. Integrating Design with Coding Agent <a class="header-anchor" href="#_5-integrating-design-with-coding-agent" aria-label="Permalink to “5. Integrating Design with Coding Agent”">​</a></h1><h2 id="_1-preparing-design-specs" tabindex="-1">1. Preparing Design Specs <a class="header-anchor" href="#_1-preparing-design-specs" aria-label="Permalink to “1. Preparing Design Specs”">​</a></h2><p>Before handing off to the Coding Agent, prepare:</p><ol><li><strong>Logo file</strong> (PNG with transparent background)</li><li><strong>Color codes</strong> (Hex values for primary, secondary, accent colors)</li><li><strong>Typography</strong> (Font names, sizes, weights)</li><li><strong>Layout description</strong> (Section structure, spacing, responsive behavior)</li></ol><h2 id="_2-writing-coding-prompts" tabindex="-1">2. Writing Coding Prompts <a class="header-anchor" href="#_2-writing-coding-prompts" aria-label="Permalink to “2. Writing Coding Prompts”">​</a></h2><p><strong>Example Prompt</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;Build a responsive website based on the following specifications:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Brand**</span></span>
<span class="line"><span>- Logo: [attach logo file]</span></span>
<span class="line"><span>- Name: My First Website</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Colors**</span></span>
<span class="line"><span>- Primary Background: #171721 (dark)</span></span>
<span class="line"><span>- Text: #FFFFFF (white)</span></span>
<span class="line"><span>- Accent: #FF7130 (orange)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Sections**</span></span>
<span class="line"><span>1. Home - Hero with headline &#39;Welcome to My First Website&#39;, subtitle, and &#39;Get Started&#39; button</span></span>
<span class="line"><span>2. About - Brief company introduction (2-3 sentences)</span></span>
<span class="line"><span>3. Services - 3 service cards in a row</span></span>
<span class="line"><span>4. Contact - Simple form with name, email, message fields</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Requirements**</span></span>
<span class="line"><span>- Use semantic HTML5</span></span>
<span class="line"><span>- Include CSS animations for smooth transitions</span></span>
<span class="line"><span>- Mobile responsive (stack sections on mobile)</span></span>
<span class="line"><span>- Use CSS flexbox/grid for layout</span></span>
<span class="line"><span>- Add subtle hover effects on buttons and cards</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please create index.html with embedded CSS and basic JavaScript for mobile menu.&quot;</span></span></code></pre></div><h2 id="_3-iterating-with-coding-agent" tabindex="-1">3. Iterating with Coding Agent <a class="header-anchor" href="#_3-iterating-with-coding-agent" aria-label="Permalink to “3. Iterating with Coding Agent”">​</a></h2><ul><li>Initial code → Test and review → Provide feedback → Refine until satisfied</li></ul><p><img src="`+g+'" alt=""><img src="'+c+`" alt=""></p><hr><h1 id="_6-practical-example-building-a-personal-portfolio" tabindex="-1">6. Practical Example: Building a Personal Portfolio <a class="header-anchor" href="#_6-practical-example-building-a-personal-portfolio" aria-label="Permalink to “6. Practical Example: Building a Personal Portfolio”">​</a></h1><h2 id="_1-project-overview" tabindex="-1">1. Project Overview <a class="header-anchor" href="#_1-project-overview" aria-label="Permalink to “1. Project Overview”">​</a></h2><p>Let&#39;s build a personal portfolio website with:</p><ul><li>Clean, modern design</li><li>About section with photo</li><li>Skills showcase</li><li>Project portfolio grid</li><li>Contact form</li></ul><h2 id="_2-step-by-step-implementation" tabindex="-1">2. Step-by-Step Implementation <a class="header-anchor" href="#_2-step-by-step-implementation" aria-label="Permalink to “2. Step-by-Step Implementation”">​</a></h2><h3 id="step-1-design-phase" tabindex="-1">Step 1: Design Phase <a class="header-anchor" href="#step-1-design-phase" aria-label="Permalink to “Step 1: Design Phase”">​</a></h3><p><strong>Logo Design Prompt</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;Design a minimalist logo for a personal portfolio.</span></span>
<span class="line"><span>Brand name: &#39;John Doe&#39;</span></span>
<span class="line"><span>Style: Clean, professional, modern</span></span>
<span class="line"><span>Colors: Dark blue (#1E3A8A) and white</span></span>
<span class="line"><span>Format: PNG with transparent background&quot;</span></span></code></pre></div><p><strong>Layout Design Prompt</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;Create a personal portfolio website layout:</span></span>
<span class="line"><span>- Single page with smooth scroll</span></span>
<span class="line"><span>- Dark theme with blue accents</span></span>
<span class="line"><span>- Sections: Hero (with photo placeholder), About, Skills, Projects, Contact</span></span>
<span class="line"><span>- Modern, professional aesthetic</span></span>
<span class="line"><span>- Include responsive mobile view&quot;</span></span></code></pre></div><h3 id="step-2-development-phase" tabindex="-1">Step 2: Development Phase <a class="header-anchor" href="#step-2-development-phase" aria-label="Permalink to “Step 2: Development Phase”">​</a></h3><p><strong>Coding Prompt</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;Create a personal portfolio website with these specs:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Visual Design**</span></span>
<span class="line"><span>- Dark theme: #0F172A background, #F8FAFC text</span></span>
<span class="line"><span>- Accent color: #3B82F6 (blue)</span></span>
<span class="line"><span>- Font: Inter from Google Fonts</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Sections**</span></span>
<span class="line"><span>1. Hero: Name, title, brief tagline, &#39;View Work&#39; CTA button</span></span>
<span class="line"><span>2. About: Photo placeholder (200x200 circle), 2-paragraph bio</span></span>
<span class="line"><span>3. Skills: Grid of skill tags (HTML, CSS, JavaScript, React, Node.js)</span></span>
<span class="line"><span>4. Projects: 3-column grid with project cards (image, title, description, link)</span></span>
<span class="line"><span>5. Contact: Form with name, email, message fields and submit button</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Technical**</span></span>
<span class="line"><span>- Responsive: Single column on mobile, 3 columns for projects</span></span>
<span class="line"><span>- Smooth scroll between sections</span></span>
<span class="line"><span>- Hover effects on buttons and project cards</span></span>
<span class="line"><span>- Form validation with JavaScript</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Output as a single index.html file with embedded CSS and JS.&quot;</span></span></code></pre></div><h3 id="step-3-refinement" tabindex="-1">Step 3: Refinement <a class="header-anchor" href="#step-3-refinement" aria-label="Permalink to “Step 3: Refinement”">​</a></h3><p>Based on test results, iterate:</p><ul><li>&quot;Add more projects to the portfolio&quot;</li><li>&quot;Change accent color to green (#10B981)&quot;</li><li>&quot;Add a navigation bar that stays fixed at top&quot;</li></ul><hr><h1 id="_7-best-practices" tabindex="-1">7. Best Practices <a class="header-anchor" href="#_7-best-practices" aria-label="Permalink to “7. Best Practices”">​</a></h1><h2 id="_1-design-coding-handoff-tips" tabindex="-1">1. Design-Coding Handoff Tips <a class="header-anchor" href="#_1-design-coding-handoff-tips" aria-label="Permalink to “1. Design-Coding Handoff Tips”">​</a></h2><ol><li><strong>Be Specific</strong>: Provide exact colors, dimensions, and spacing</li><li><strong>Use References</strong>: Share example websites you like</li><li><strong>Iterate Incrementally</strong>: Start simple, add complexity later</li><li><strong>Test Responsiveness</strong>: Check how it looks on different screen sizes</li></ol><h2 id="_2-prompt-optimization" tabindex="-1">2. Prompt Optimization <a class="header-anchor" href="#_2-prompt-optimization" aria-label="Permalink to “2. Prompt Optimization”">​</a></h2><table tabindex="0"><thead><tr><th>Tip</th><th>Do</th><th>Don&#39;t</th></tr></thead><tbody><tr><td><strong>Clarity</strong></td><td>&quot;Use #FF5733 for buttons&quot;</td><td>&quot;Make it pop&quot;</td></tr><tr><td><strong>Context</strong></td><td>&quot;For a SaaS landing page...&quot;</td><td>Just &quot;make a website&quot;</td></tr><tr><td><strong>Constraints</strong></td><td>&quot;Max 3 colors, no animations&quot;</td><td>&quot;Make it beautiful&quot;</td></tr><tr><td><strong>Feedback</strong></td><td>&quot;The hero section is too tall, reduce padding&quot;</td><td>&quot;Fix it&quot;</td></tr></tbody></table><h2 id="_3-common-workflow-patterns" tabindex="-1">3. Common Workflow Patterns <a class="header-anchor" href="#_3-common-workflow-patterns" aria-label="Permalink to “3. Common Workflow Patterns”">​</a></h2><ol><li><strong>Design-First</strong>: Design complete → Code implementation</li><li><strong>Parallel</strong>: Design and code simultaneously with iteration</li><li><strong>Iterative</strong>: Quick prototype → Refine design → Enhance code</li></ol><hr><h1 id="_8-summary" tabindex="-1">8. Summary <a class="header-anchor" href="#_8-summary" aria-label="Permalink to “8. Summary”">​</a></h1><p>This chapter covered:</p><ol><li><strong>Design Agents</strong>: How to use AI for logo and layout design</li><li><strong>Coding Agents</strong>: How to convert designs into functional code</li><li><strong>Integration Workflow</strong>: Complete process from design to deployment</li><li><strong>Practical Examples</strong>: Step-by-step portfolio website creation</li><li><strong>Best Practices</strong>: Tips for effective AI collaboration</li></ol><p>The combination of Design Agents and Coding Agents represents a powerful workflow that can significantly accelerate website development. By clearly communicating your vision and iterating based on feedback, you can create professional websites efficiently.</p><p><strong>Key Takeaways:</strong></p><ul><li>Start with clear requirements and design specs</li><li>Use specific, actionable prompts</li><li>Iterate based on testing and feedback</li><li>Leverage both design and coding AI tools together</li></ul><p><strong>Next Steps:</strong></p><ul><li>Try creating your own website using this workflow</li><li>Experiment with different Design Agents (Mastergo, Figma)</li><li>Explore advanced Coding Agent features (Cursor, Lovable)</li><li>Build a complete project portfolio using AI assistance</li></ul><p>Happy building! 🚀</p><p><img src="`+d+'" alt=""></p>',102)])])}const C=a(h,[["render",u]]);export{P as __pageData,C as default};
